    eqs: [['\\delta m\\dot v = \\frac{T_mG\\eta_g}{r_w} - F_{brake} - F_{rr} - F_d - F_g', ''], ['P_b = T_m\\omega_m + P_{loss,m} + P_{loss,inv} + P_{aux},\\quad I_b = \\frac{E - \\sqrt{E^2 - 4R_0P_b}}{2R_0}', ''], ['\\dot z = -\\frac{I_b}{3600Q}', '']],
    params: [{ id: 'scen', l: 'Scenario', type: 'select', str: true, v: 'auto', opts: [['auto', 'Accelerate – cruise – brake (repeating)'], ['manual', 'Manual pedals (sliders)']] }, { id: 'acc', l: 'Accelerator (manual)', u: '%', min: 0, max: 100, step: 1, v: 40 }, { id: 'brk', l: 'Brake (manual)', u: '%', min: 0, max: 100, step: 1, v: 0 }, { id: 'grade', l: 'Road grade', u: '%', min: -10, max: 15, step: 0.5, v: 0 }, { id: 'mode', l: 'Drive mode', type: 'seg', str: true, v: 'NORMAL', opts: [['ECO', 'ECO'], ['NORMAL', 'NORMAL'], ['SPORT', 'SPORT']] }, { id: 'regen', l: 'Regeneration level', u: '%', min: 0, max: 100, step: 5, v: 70 }],
