        charts: [lc('w', 'Wheel torque and wheel power', 'Time (s)', 'N·m / kW', [S('Wheel power (kW)', b.t, b.Pw), S('Wheel torque /10 (N·m)', b.t, b.Ft.map(f => f * REF4.r / 10))]), lc('m', 'Motor torque and motor power', 'Time (s)', 'N·m / kW', [S('Motor torque (N·m)', b.t, b.Tm), S('Motor power (kW)', b.t, b.Pm)]), lc('ib', 'Battery current', 'Time (s)', 'A', [S('I_b', b.t, b.Ib)]), lc('e', 'Cumulative battery energy', 'Time (s)', 'kWh', [S('E_b', b.t, b.E)]), ...(fw ? [lc('cmp', 'Forward model speed vs cycle (backward assumes exact tracking)', 'Time (s)', 'km/h', [S('Cycle (backward)', b.t, b.v), S('Forward model', fw.X, fw.V, { dash: [4, 3] })], { wide: true })] : [])],
        obs: { cols: ['Quantity', 'Backward model', 'Forward model'], rows: [['Consumption (Wh/km)', b.Whkm, fw ? fw.Whkm : '–'], ['Net energy (kWh)', b.Enet, fw ? fw.E : '–'], ['Speed tracking', 'exact by construction', fw ? `RMS error ${fw.rms.toFixed(2)} km/h` : '–'], ['Driver model', 'not needed', 'PI driver'], ['Captures actuator limits', 'no (only checks)', 'yes'], ['Computation time (ms)', tb, tf], ['Typical use', 'energy, sizing, range', 'control design, dynamics, HIL']] },
